// ERZEUGT von scripts/make-intro.mjs aus vendor/startanimation/startanimation.html – nicht von Hand ändern.
// Quelle: Link-Suite/Konzepte/_Startanimation (gemeinsame Startanimation der Suite).
/* eslint-disable */
import cssUrl from "./startanimation.css?url";

const MARKUP = "<div class=\"bg\"></div>\n<div class=\"under\"><div class=\"card\"><img id=\"underLogo\" alt=\"\"><p id=\"underTag\"></p><div class=\"ph\">Hier erscheint der Startbildschirm des Programms.</div></div></div>\n<div class=\"intro\" id=\"intro\" role=\"img\" aria-label=\"Link-Suite\"><div class=\"stage\" id=\"stage\"></div></div>\n<div class=\"skip\" id=\"skip\"><span data-k=\"intro.skip\"></span> <kbd data-k=\"intro.key\"></kbd> <span data-k=\"intro.or\"></span></div>\n<div class=\"bar\" id=\"bar\"></div>";

/** Startanimation als Schicht in `host` (Shadow-Root). `app`: suite | lj | vj | vd | pl | net | cr | db. */
export function mountIntro(host, app, text) {
  const root = host.attachShadow({ mode: "open" });
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = cssUrl;
  // Bis die Styles da sind, nichts zeigen (sonst blitzt der Platzhalter ungestaltet auf); die Schicht deckt ab.
  const shadowBox = document.createElement("div");
  shadowBox.style.visibility = "hidden";
  link.addEventListener("load", () => { shadowBox.style.visibility = ""; }, { once: true });
  root.append(link, shadowBox);
  const wrap = document.createElement("div");
  wrap.innerHTML = MARKUP;
  shadowBox.append(...wrap.childNodes);
  for (const el of root.querySelectorAll("[data-k]")) el.textContent = text(el.getAttribute("data-k"));
  const QUERY = "?app=" + encodeURIComponent(app) + "&ui=0";

const BRANDS = {"suite": {"name": "Link-Suite", "short": "Suite", "tag": "Kostenlose Programme für Veranstaltungstechnik.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, -6.5, 591.54, 106.0], "sign": {"w": 108.0, "y": 0.0, "h": 90.0}, "iconSignW": 564, "iconSignCy": 700}, "lj": {"name": "LJ Link", "short": "LJ", "tag": "Zeigt dem LJ, was der Sound macht.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 2.0, 507.49, 96.0], "sign": {"w": 166.0, "y": 10.0, "h": 80.0}, "iconSignW": 564.0, "iconSignCy": 710.0}, "vj": {"name": "VJ-Link", "short": "VJ", "tag": "Einfache VJ-Software für LJs.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 4.35, 545.49, 84.69], "sign": {"w": 166.0, "y": 42.0, "h": 26.0}, "iconSignW": 564.0, "iconSignCy": 705.0}, "vd": {"name": "VD-Link", "short": "VD", "tag": "3D-Lichtvisualisierer für Art-Net und sACN.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 4.35, 557.67, 87.65], "sign": {"w": 166.0, "y": 32.0, "h": 52.0}, "iconSignW": 596.0, "iconSignCy": 725.0}, "pl": {"name": "PL Link", "short": "PL", "tag": "Patch & Load: DMX-Adressen und Stromlast planen.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 4.35, 513.55, 83.65], "sign": {"w": 166.0, "y": 30.0, "h": 48.0}, "iconSignW": 564.0, "iconSignCy": 716.0}, "net": {"name": "NET Link", "short": "NET", "tag": "Zeigt, wer im Show-Netz ist, und findet, was nicht passt.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 4.35, 585.33, 83.65], "sign": {"w": 166.0, "y": 25.0, "h": 44.15}, "iconSignW": 564.0, "iconSignCy": 713.19}, "cr": {"name": "Crew Link", "short": "CR", "tag": "Ablauf der Nacht: eine Uhr für alle.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, 3.99, 634.28, 85.09], "sign": {"w": 166.0, "y": 14.0, "h": 66.0}, "iconSignW": 552.0, "iconSignCy": 704.0}, "db": {"name": "dB Link", "short": "dB", "tag": "Lautstärke messen, warnen und protokollieren.", "icon": "data:image/svg+xml;base64,", "symbol": "data:image/svg+xml;base64,", "logo": "data:image/svg+xml;base64,", "logoBox": [-8.0, -14.0, 518.45, 108.0], "sign": {"w": 166.0, "y": -6.0, "h": 92.0}, "iconSignW": 470.0, "iconSignCy": 662.0}};
const ORDER = ['lj', 'vj', 'vd', 'pl', 'net', 'cr', 'db'];

// ------------------------------------------------------------------ Parameter
const Q = new URLSearchParams(QUERY);
const APP = BRANDS[Q.get('app')] ? Q.get('app') : 'pl';
const SPEED = Math.min(4, Math.max(0.05, Number(Q.get('speed')) || 1));
const REDUCED = Q.get('reduced') === '1' || matchMedia('(prefers-reduced-motion: reduce)').matches;
const HOLD_AT = Q.has('t') ? Number(Q.get('t')) : null;
const LOOP = Q.get('loop') === '1';
const UI = Q.get('ui') !== '0';

// ------------------------------------------------------------------ Aufbau
const stage = root.getElementById('stage');
const fit = () => { const w = innerWidth || document.documentElement.clientWidth || 1000, h = innerHeight || document.documentElement.clientHeight || 600; stage.style.setProperty('--k', Math.max(.2, Math.min(w / 1000, h / 600, 1.4))); };
fit(); addEventListener('resize', fit); addEventListener('load', fit); requestAnimationFrame(fit);
const img = (src, w, h) => { const i = new Image(); i.src = src; i.alt = ''; i.style.width = w + 'px'; if (h) i.style.height = h + 'px'; stage.appendChild(i); return i; };
const T = BRANDS[APP];
root.getElementById('underLogo').src = T.logo;
root.getElementById('underTag').textContent = T.tag;
root.getElementById('intro').setAttribute('aria-label', T.name);

// Maße (Entwurfsfläche 1000 × 600, Ursprung Mitte)
const ICON = 92, GAP = 22, ROW_Y = 70, SUITE_W = 150;
const LOGO_H = 84;
const logoW = LOGO_H * T.logoBox[2] / T.logoBox[3];
// Lage des Zeichens im Logo (das Zeichen steht links, Breite = sign.w in Logo-Einheiten)
const k = LOGO_H / T.logoBox[3];
const signCx = (T.sign.w / 2 - T.logoBox[0]) * k - logoW / 2;
const signCy = (T.sign.y + T.sign.h / 2 - (T.logoBox[1] + T.logoBox[3] / 2)) * k;

const tr = (x, y, s = 1) => `translate(-50%,-50%) translate(${x}px,${y}px) scale(${s})`;
const anims = [];
const seen = new Set();
// Erstes Stück je Element füllt rückwärts (Anfangszustand), alle weiteren nur vorwärts – sonst überdeckt ein späteres
// Stück mit seinem Anfangswert schon vor seinem Start die früheren.
const run = (el, frames, delay, dur, easing = 'cubic-bezier(.2,.8,.2,1)') => {
  const fill = seen.has(el) ? 'forwards' : 'both'; seen.add(el);
  const a = el.animate(frames, {delay: delay / SPEED, duration: dur / SPEED, easing, fill});
  anims.push(a); return a;
};
const total = () => Math.max(...anims.map(a => (a.effect.getTiming().delay + a.effect.getTiming().duration)));

// ------------------------------------------------------------------ Ablauf
function build() {
  const suite = img(BRANDS.suite.symbol, SUITE_W);
  const logo = img(T.logo, logoW, LOGO_H);
  logo.style.clipPath = 'inset(0 0 0 0)';
  const under = root.querySelector('.under');

  if (REDUCED) {
    // Ohne Bewegung: Logo blendet ruhig ein und wieder aus, etwa 1 s.
    run(logo, [{opacity: 0, transform: tr(0, 0)}, {opacity: 1, transform: tr(0, 0)}], 0, 300, 'ease-out');
    run(logo, [{opacity: 1}, {opacity: 0}], 800, 250, 'ease-in');
    run(under, [{opacity: 0}, {opacity: 1}], 800, 250, 'ease-out');
    return;
  }

  // 1 · 0–350 ms: Zeichen der Link-Suite erscheint
  run(suite, [{opacity: 0, transform: tr(0, 0, .82)}, {opacity: 1, transform: tr(0, 0, 1)}], 0, 380, 'cubic-bezier(.2,.7,.2,1)');
  // 2 · 300–950 ms: Suite rückt nach oben, die sieben Programme fächern sich aus ihr auf
  run(suite, [{opacity: 1, transform: tr(0, 0, 1)}, {opacity: 1, transform: tr(0, -96, .62)}], 320, 520);
  const icons = {};
  const rowW = ORDER.length * ICON + (ORDER.length - 1) * GAP;
  ORDER.forEach((id, i) => {
    const x = -rowW / 2 + ICON / 2 + i * (ICON + GAP);
    const el = icons[id] = img(BRANDS[id].icon, ICON);
    el.dataset.x = x;
    run(el, [{opacity: 0, transform: tr(0, -96, .25)}, {opacity: 1, transform: tr(x, ROW_Y, 1)}], 380 + i * 45, 480);
  });
  // 3 · 1000–1500 ms: alle laufen in das gewählte Programm zusammen
  const focusX = APP === 'suite' ? 0 : Number(icons[APP].dataset.x);
  ORDER.forEach((id, i) => {
    const el = icons[id], x = Number(el.dataset.x);
    if (id === APP) {
      run(el, [{opacity: 1, transform: tr(x, ROW_Y, 1)}, {opacity: 1, transform: tr(0, 0, 1.55)}], 1000, 480, 'cubic-bezier(.55,0,.2,1)');
    } else {
      const order = Math.abs(x - focusX);
      run(el, [{opacity: 1, transform: tr(x, ROW_Y, 1)}, {opacity: 0, transform: tr(APP === 'suite' ? 0 : 0, APP === 'suite' ? -96 : 0, .35)}], 1000 + order / 8, 420, 'cubic-bezier(.55,0,.6,1)');
    }
  });
  const signEdge = ((T.sign.w - T.logoBox[0]) * k + 6) / logoW;   // Anteil der Logobreite bis hinter das Zeichen
  const clipSign = `inset(0 ${100 - signEdge * 100}% 0 0)`;
  if (APP === 'suite') {
    // Dachmarke: die Programme kehren in das Zeichen zurück, das zum Logo wird
    run(suite, [{opacity: 1, transform: tr(0, -96, .62)}, {opacity: 1, transform: tr(signCx, signCy, (T.sign.w * k) / SUITE_W)}], 1150, 520, 'cubic-bezier(.55,0,.2,1)');
    run(suite, [{opacity: 1}, {opacity: 0}], 1700, 200, 'linear');
    run(logo, [{opacity: 0, clipPath: clipSign, transform: tr(0, 0)}, {opacity: 1, clipPath: clipSign, transform: tr(0, 0)}], 1680, 220, 'linear');
  } else {
    run(suite, [{opacity: 1, transform: tr(0, -96, .62)}, {opacity: 0, transform: tr(0, -120, .5)}], 1000, 380, 'ease-in');
    // 4 · 1500–2150 ms: Das Zeichen des Logos liegt genau auf dem Zeichen im Icon. Das Icon blendet aus,
    //     das Logo wächst auf seine Größe, der Name wischt von links herein.
    const el = icons[APP];
    const big = ICON * 1.55;
    const s0 = (big * T.iconSignW / 1024) / (T.sign.w * k);
    const iy = big * (T.iconSignCy - 512) / 1024;
    const start = tr(-s0 * signCx, iy - s0 * signCy, s0);
    run(el, [{opacity: 1}, {opacity: 0}], 1500, 200, 'linear');
    run(logo, [{opacity: 0, clipPath: clipSign, transform: start}, {opacity: 1, clipPath: clipSign, transform: start}], 1500, 200, 'linear');
    run(logo, [{transform: start}, {transform: tr(0, 0, 1)}], 1680, 420, 'cubic-bezier(.3,.7,.2,1)');
  }
  run(logo, [{clipPath: clipSign}, {clipPath: 'inset(0 0% 0 0)'}], 1820, 360, 'cubic-bezier(.3,.7,.2,1)');
  // 5 · 2150–2450 ms: kurz stehen, dann gibt die Animation den Startbildschirm frei
  run(logo, [{opacity: 1, transform: tr(0, 0, 1)}, {opacity: 0, transform: tr(0, -8, .98)}], 2200, 250, 'ease-in');
  run(under, [{opacity: 0}, {opacity: 1}], 2220, 260, 'ease-out');
}

// ------------------------------------------------------------------ Ende, Überspringen
let finished = false;
function finish(skipped) {
  if (finished) return; finished = true;
  const intro = root.getElementById('intro');
  anims.forEach(a => a.cancel());
  root.getElementById('skip').style.display = 'none';
  const under = root.querySelector('.under');
  if (skipped) {
    // Überspringen: in 150 ms weich ausblenden – nie hart schneiden, nie aufblitzen
    intro.animate([{opacity: 1}, {opacity: 0}], {duration: 150, fill: 'both'});
    under.animate([{opacity: 0}, {opacity: 1}], {duration: 150, fill: 'both'});
  } else { intro.style.opacity = 0; under.style.opacity = 1; }
  intro.style.pointerEvents = 'none';
  dispatchEvent(new CustomEvent('linksuite-intro-done', {detail: {app: APP, skipped}}));
  if (LOOP) setTimeout(() => location.reload(), 900);
}

build();
if (HOLD_AT !== null) {
  anims.forEach(a => { a.pause(); a.currentTime = HOLD_AT / SPEED; });
  root.getElementById('skip').style.display = 'none';
} else {
  Promise.all(anims.map(a => a.finished)).then(() => finish(false)).catch(() => {});
  addEventListener('keydown', e => { if (!e.metaKey && !e.ctrlKey) finish(true); });
  addEventListener('pointerdown', e => { if (!e.target.closest('.bar')) finish(true); });
}

// ------------------------------------------------------------------ Prüfleiste
if (UI && HOLD_AT === null) {
  const bar = root.getElementById('bar');
  const url = p => '?' + new URLSearchParams({...Object.fromEntries(Q), ...p});
  ['suite', ...ORDER].forEach(id => bar.insertAdjacentHTML('beforeend', `<a href="${url({app: id})}" class="${id === APP ? 'on' : ''}">${BRANDS[id].short}</a>`));
  bar.insertAdjacentHTML('beforeend', `<a href="${url({})}">Nochmal</a><a href="${url({speed: SPEED === 1 ? 0.25 : 1})}">${SPEED === 1 ? 'Zeitlupe' : 'Normal'}</a><a href="${url({reduced: REDUCED ? 0 : 1})}">${REDUCED ? 'Mit Bewegung' : 'Reduzierte Bewegung'}</a><span>${Math.round(total() * SPEED)} ms</span>`);
} else root.getElementById('bar').remove();

}
